{
    (void)ctx;
    (void)format;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }
    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *data = malloc(fsize);
    fread(data, 1, fsize, f);
    fclose(f);

    ptls_minicrypto_log_ctx_t ctx = {NULL, log_printf};

    /* Simulate the fuzzer logic - test all paths */
    if (fsize < 2) return 0;
    size_t bytes_max = (data[0] << 8) + data[1];
    if (bytes_max == 0) return 0;
    if (bytes_max > fsize - 2) bytes_max = fsize - 2;

    uint8_t *bytes = malloc(bytes_max);
    memcpy(bytes, data + 2, bytes_max);

    /* Test path 0: ptls_asn1_validation */
    ptls_asn1_validation(bytes, bytes_max, &ctx);

    /* Test path 1: ptls_asn1_get_expected_type_and_length */
    if (bytes_max > 0) {
        size_t byte_index = 0;
        uint32_t length;
        int indefinite_length;
        size_t last_byte;
        int decode_error = 0;
        uint8_t expected_type = bytes[0];
        ptls_asn1_get_expected_type_and_length(bytes, bytes_max, byte_index, expected_type, 
            &length, &indefinite_length, &last_byte, &decode_error, &ctx);
    }

    free(bytes);
    free(data);
    return 0;
}
